import React, { useEffect, useState } from 'react';
import { Container, Row, Col, Card, Form, Button, Table, InputGroup } from 'react-bootstrap';
import { useAuth } from '../contexts/AuthContext';
import { apiService, PurchaseRequest } from '../services/api';
import Toast from '../components/Toast';
import LoadingSpinner from '../components/LoadingSpinner';

interface ApprovedRow extends PurchaseRequest {
  no: number;
  selected: boolean;
}

const SupplierSearch: React.FC = () => {
  const { user } = useAuth();
  const [approvedPRs, setApprovedPRs] = useState<ApprovedRow[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(false);
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [toastType, setToastType] = useState<'success' | 'error' | 'warning' | 'info'>('info');

  useEffect(() => {
    loadApprovedPRs();
  }, []);

  const loadApprovedPRs = async () => {
    try {
      setLoading(true);
      const prs = await apiService.getPurchaseRequests(false);
      const approved = prs
        .filter((pr) => pr.status?.toLowerCase() === 'approved')
        .map((pr, idx) => ({
          ...pr,
          no: idx + 1,
          selected: false,
        }));
      setApprovedPRs(approved);
    } catch (error: any) {
      console.error('Failed to load approved purchase requests:', error);
      setToastMessage('Failed to load approved purchase requests');
      setToastType('error');
      setShowToast(true);
    } finally {
      setLoading(false);
    }
  };

  const handleSelectAll = (checked: boolean) => {
    setApprovedPRs((rows) => rows.map((r) => ({ ...r, selected: checked })));
  };

  const handleSelectRow = (index: number) => {
    setApprovedPRs((rows) =>
      rows.map((r, i) => (i === index ? { ...r, selected: !r.selected } : r))
    );
  };

  const handleUseSelected = () => {
    const selected = approvedPRs.filter((r) => r.selected);
    if (selected.length === 0) {
      setToastMessage('Please select at least one approved purchase request');
      setToastType('warning');
      setShowToast(true);
      return;
    }
    setToastMessage(`Selected ${selected.length} approved purchase request(s)`);
    setToastType('success');
    setShowToast(true);
    // TODO: Wire this selection to downstream flow (e.g., canvass, supplier assignment)
  };

  const filtered = approvedPRs.filter((pr) => {
    const term = searchTerm.toLowerCase();
    return (
      pr.pr_number.toLowerCase().includes(term) ||
      (pr.entity_name || '').toLowerCase().includes(term) ||
      (pr.remark || '').toLowerCase().includes(term)
    );
  });

  const allSelected = filtered.length > 0 && filtered.every((r) => r.selected);

  const formatCurrency = (amount: number) =>
    new Intl.NumberFormat('en-PH', { style: 'currency', currency: 'PHP', minimumFractionDigits: 2 }).format(
      amount || 0
    );

  return (
    <Container fluid className="py-4">
      <Row className="mb-3">
        <Col>
          <h2 className="mb-1">Approved Purchase Requests</h2>
          <p className="text-muted mb-0">Select approved purchase requests for canvassing.</p>
        </Col>
        <Col className="text-end">
          <Button variant="outline-primary" size="sm" onClick={loadApprovedPRs} disabled={loading}>
            {loading ? (
              <>
                <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true" />
                Refreshing...
              </>
            ) : (
              <>
                <i className="bi bi-arrow-clockwise me-2"></i>
                Refresh
              </>
            )}
          </Button>
        </Col>
      </Row>

      <Card>
        <Card.Header>
          <div className="d-flex justify-content-between align-items-center">
            <h5 className="mb-0">Approved Requests</h5>
            <div style={{ width: '280px' }}>
              <InputGroup>
                <InputGroup.Text>
                  <i className="bi bi-search"></i>
                </InputGroup.Text>
                <Form.Control
                  placeholder="Search PR number, entity, remark..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
              </InputGroup>
            </div>
          </div>
        </Card.Header>
        <Card.Body>
          {loading ? (
            <div className="text-center py-4">
              <LoadingSpinner size="lg" text="Loading approved requests..." />
            </div>
          ) : (
            <div className="table-responsive">
              <Table striped bordered hover>
                <thead>
                  <tr>
                    <th style={{ width: '6%' }}>
                      <Form.Check
                        type="checkbox"
                        checked={allSelected}
                        onChange={(e) => handleSelectAll(e.target.checked)}
                        aria-label="Select all"
                      />
                    </th>
                    <th style={{ width: '10%' }}>P.R. Number</th>
                    <th style={{ width: '18%' }}>Entity / Requested By</th>
                    <th style={{ width: '14%' }}>Office / Section</th>
                    <th style={{ width: '12%' }}>Date Requested</th>
                    <th style={{ width: '12%' }}>Total Amount</th>
                    <th>Remark</th>
                  </tr>
                </thead>
                <tbody>
                  {filtered.length === 0 ? (
                    <tr>
                      <td colSpan={7} className="text-center text-muted py-4">
                        No approved purchase requests found
                      </td>
                    </tr>
                  ) : (
                    filtered.map((pr, idx) => (
                      <tr key={pr.id || idx}>
                        <td className="text-center">
                          <Form.Check
                            type="checkbox"
                            checked={pr.selected}
                            onChange={() => handleSelectRow(
                              approvedPRs.findIndex((r) => r.id === pr.id)
                            )}
                            aria-label={`Select ${pr.pr_number}`}
                          />
                        </td>
                        <td className="fw-semibold">{pr.pr_number}</td>
                        <td>{pr.entity_name}</td>
                        <td>{pr.office_section}</td>
                        <td>{new Date(pr.date_created).toLocaleDateString('en-PH')}</td>
                        <td>{formatCurrency(pr.total_amount)}</td>
                        <td>{pr.remark || 'No remarks'}</td>
                      </tr>
                    ))
                  )}
                </tbody>
              </Table>
            </div>
          )}
          <div className="d-flex justify-content-end mt-3">
            <Button variant="primary" onClick={handleUseSelected} disabled={loading || filtered.length === 0}>
              Use Selected
            </Button>
          </div>
        </Card.Body>
      </Card>

      <Toast
        show={showToast}
        message={toastMessage}
        type={toastType}
        onClose={() => setShowToast(false)}
      />
    </Container>
  );
};

export default SupplierSearch;
